import{_ as o,o as n,c as r,a5 as s}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"模块具有 单例（Singleton）","description":"在 ​ ​ ES6 模块（ES Module） ​ ​ 中，模块的代码（包括变量声明和函数定义）​ ​ 只会执行一次 ​ ​，无论被导入（import）多少次。模块具有 ​ ​ 单例（Singleton） ​ ​ 特性，即模块的代码在首次加载时执行，后续导入会直接使用缓存的结果。","frontmatter":{"title":"模块具有 单例（Singleton）","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"在 ​ ​ ES6 模块（ES Module） ​ ​ 中，模块的代码（包括变量声明和函数定义）​ ​ 只会执行一次 ​ ​，无论被导入（import）多少次。模块具有 ​ ​ 单例（Singleton） ​ ​ 特性，即模块的代码在首次加载时执行，后续导入会直接使用缓存的结果。","sidebarWeight":53,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/模块具有 ​​单例（Singleton）.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/模块具有 单例（Singleton）.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/模块具有 单例（Singleton）.md"}'),g={name:"posts/JavaScript系统教程/06-模块化与工程化/模块具有 单例（Singleton）.md"};function e(a,t,l,d,i,u){return n(),r("div",null,[...t[0]||(t[0]=[s('<div><h1 id="模块具有-单例-singleton" tabindex="-1">模块具有 单例（Singleton） <a class="header-anchor" href="#模块具有-单例-singleton" aria-label="Permalink to &quot;模块具有 单例（Singleton）&quot;">​</a></h1><blockquote><p>本节目标：理解“模块具有 单例（Singleton）”的核心思路，并能把它用于实际开发或面试表达。 在 ​<strong>​****ES6 模块（ES Module）****​</strong>​ 中，模块的代码（包括变量声明和函数定义）​<strong>​<strong><strong>只会执行一次</strong></strong>​</strong>​，无论被导入（import）多少次。模块具有 ​<strong>​****单例（Singleton）****​</strong>​ 特性，即模块的代码在首次加载时执行，后续导入会直接使用缓存的结果。</p></blockquote><p><strong>​​<strong><strong>1. 变量声明：只初始化一次</strong></strong>​​</strong><strong>​​<strong><strong>示例</strong></strong>​​</strong> // module.jslet count = 0;export const increment = () =&gt; { count++; return count;}; // main.jsimport { increment } from &#39;./module.js&#39;; console.log(increment()); // 1console.log(increment()); // 2</p><ul><li>​<strong>​<strong><strong>count 变量只初始化一次</strong></strong>​</strong>​，即使多次调用 increment()，它仍然会基于同一个 count 进行递增。</li></ul><p>**​​**<strong>2. 函数调用：只执行一次（如果不在模块顶层）<strong><strong>​​</strong> **​​</strong></strong>示例（函数定义 vs. 立即执行）**<strong>​​</strong> // module.jsexport const getRandom = () =&gt; Math.random(); // 每次调用都会执行 export const randomValue = Math.random(); // 只在模块加载时计算一次 // main.jsimport { getRandom, randomValue } from &#39;./module.js&#39;; console.log(getRandom()); // 每次调用返回不同的随机数console.log(getRandom()); // 不同值 console.log(randomValue); // 始终相同（模块加载时计算的值）console.log(randomValue); // 同上</p><ul><li>​<strong>​****getRandom()****​</strong>​ 是函数声明，每次调用都会重新计算。</li><li>​<strong>​<strong><strong>randomValue</strong></strong>​</strong>​ 是模块顶层变量，只在模块加载时计算一次，后续导入直接使用缓存值。</li></ul><p><strong>​​<strong><strong>3. 模块的顶层代码只执行一次</strong></strong>​​</strong><strong>​​<strong><strong>示例</strong></strong>​​</strong> // module.jsconsole.log(&quot;Module initialized!&quot;); // 只会在第一次导入时执行 export const data = { key: &quot;value&quot; }; // main.jsimport &#39;./module.js&#39;; // 打印 &quot;Module initialized!&quot;import &#39;./module.js&#39;; // 不会再次执行，直接使用缓存</p><ul><li>​<strong>​<strong><strong>模块的顶层代码（如 console.log）在首次导入时执行</strong></strong>​</strong>​，后续导入不会重复执行。</li></ul><p><strong>​​<strong><strong>4. 循环引用时，模块仍然只执行一次</strong></strong>​​</strong><strong>​​<strong><strong>示例</strong></strong>​​</strong> // a.jsimport { b } from &#39;./b.js&#39;;console.log(&quot;a.js loaded&quot;);export const a = &quot;A&quot;; // b.jsimport { a } from &#39;./a.js&#39;;console.log(&quot;b.js loaded&quot;);export const b = &quot;B&quot;; // main.jsimport &#39;./a.js&#39;; ​<strong>​****输出：****​</strong>​ b.js loadeda.js loaded</p><ul><li>即使 a.js 和 b.js 互相引用，​<strong>​<strong><strong>每个模块仍然只执行一次</strong></strong>​</strong>​，不会导致无限循环。</li></ul><p><strong>​​<strong><strong>总结</strong></strong>​​</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>情况</strong></td><td><strong>是否只执行一次？</strong></td></tr><tr><td>​<strong>​****模块顶层变量（const, let, var）****​</strong>​</td><td>✅ 是</td></tr><tr><td>​<strong>​****模块顶层函数声明（function）****​</strong>​</td><td>✅ 是（但调用时会执行）</td></tr><tr><td>​<strong>​****模块顶层立即执行的代码（如 console.log）****​</strong>​</td><td>✅ 是</td></tr><tr><td>​<strong>​****模块内函数调用（如 getRandom()）****​</strong>​</td><td>❌ 否（每次调用都会执行）</td></tr><tr><td>​<strong>​****动态导入（import()）****​</strong>​</td><td>✅ 是（相同模块只加载一次）</td></tr></tbody></table><p><strong>​​<strong><strong>关键结论</strong></strong>​​</strong></p><ul><li>​<strong>​<strong><strong>ES6 模块是单例的</strong></strong>​</strong>​，模块代码（变量、函数定义、顶层逻辑）​<strong>​<strong><strong>只会在第一次导入时执行</strong></strong>​</strong>​。</li><li>​<strong>​<strong><strong>后续导入直接使用缓存</strong></strong>​</strong>​，不会重复执行。</li><li>​<strong>​<strong><strong>函数调用（如 getRandom()）仍然可以多次执行</strong></strong>​</strong>​，但函数本身只定义一次。</li></ul><p>这种机制确保了模块的高效性和一致性，适用于全局状态管理（如 Redux、Vuex 等）。 &gt; 来自 &lt;<a href="https://yuanbao.tencent.com/chat/naQivTmsDa/0e52abee-e866-4015-963e-de1ed20ae8a2" target="_blank" rel="noreferrer">https://yuanbao.tencent.com/chat/naQivTmsDa/0e52abee-e866-4015-963e-de1ed20ae8a2</a>&gt;</p></div>',1)])])}const p=o(g,[["render",e]]);export{m as __pageData,p as default};
